// Generates src/lib/inline-media.ts — base64 data URIs for landing-critical
// images, so the homepage renders fully even when edge protection blocks
// image subresource requests (same self-containment strategy as inlined CSS).
// Run: node scripts/generate-inline-media.mjs   (commit the generated file)
import sharp from "sharp";
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");
const pub = (p) => resolve(root, "public", p.replace(/^\//, ""));

async function jpeg(path, width, quality) {
  const buf = await sharp(pub(path)).resize({ width, withoutEnlargement: true }).jpeg({ quality, mozjpeg: true }).toBuffer();
  return `data:image/jpeg;base64,${buf.toString("base64")}`;
}
async function webp(path, height, quality) {
  const buf = await sharp(pub(path)).resize({ height, withoutEnlargement: true }).webp({ quality }).toBuffer();
  return `data:image/webp;base64,${buf.toString("base64")}`;
}

const heroPoster = await jpeg("/videos/hero-home-poster.jpg", 1280, 55);
const portrait = await jpeg("/jb-portrait.jpg", 750, 62);
const logoIsl = await webp("/schools/isl.jpg", 96, 80);
const logoLgs = await webp("/schools/lgs.png", 96, 80);
const logoLacas = await webp("/schools/lacas.webp", 96, 80);

const out = `// AUTO-GENERATED by scripts/generate-inline-media.mjs — do not edit by hand.
// Base64 data URIs for landing-critical images. Keeps the homepage fully
// self-contained (renders even if image subresource requests are blocked).

export const HERO_POSTER_DATA_URI = ${JSON.stringify(heroPoster)};

export const PORTRAIT_DATA_URI = ${JSON.stringify(portrait)};

/** Inline school logos keyed by their public path. */
export const SCHOOL_LOGO_DATA_URIS: Record<string, string> = {
  "/schools/isl.jpg": ${JSON.stringify(logoIsl)},
  "/schools/lgs.png": ${JSON.stringify(logoLgs)},
  "/schools/lacas.webp": ${JSON.stringify(logoLacas)},
};
`;
writeFileSync(resolve(root, "src/lib/inline-media.ts"), out);
const kb = (s) => Math.round(s.length / 1024);
console.log(`hero ${kb(heroPoster)}KB, portrait ${kb(portrait)}KB, isl ${kb(logoIsl)}KB, lgs ${kb(logoLgs)}KB, lacas ${kb(logoLacas)}KB`);
console.log("Wrote src/lib/inline-media.ts");
